from math import gcd

def transform(grid):
    h, w = len(grid), len(grid[0])

    special_rows = [
        r for r in range(h)
        if any(v not in (1, 9) for v in grid[r])
    ]
    special_cols = [
        c for c in range(w)
        if any(grid[r][c] not in (1, 9) for r in range(h))
    ]

    def lattice(coords, limit):
        step = 0
        for a, b in zip(coords, coords[1:]):
            step = gcd(step, b - a)
        if step == 0:
            return coords
        phase = coords[0] % step
        return list(range(phase, limit, step))

    rows = lattice(special_rows, h)
    cols = lattice(special_cols, w)

    result = []
    for r0, r1 in zip(rows, rows[1:]):
        out_row = []
        for c0, c1 in zip(cols, cols[1:]):
            corner = grid[r0][c0]
            if (grid[r0][c1] == corner and
                grid[r1][c0] == corner and
                grid[r1][c1] == corner):
                out_row.append(corner)
            else:
                out_row.append(9)
        result.append(out_row)
    return result
